# Scans project skills/ and writes .cursor/skills-index.md; outputs sessionStart JSON.
$ErrorActionPreference = 'Stop'

$projectRoot = Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$skillsRoot = Join-Path $projectRoot 'skills'
$indexPath = Join-Path $projectRoot '.cursor\skills-index.md'

$excludePathPattern = '(\\|/)(agency-agents-main|\.claude|\.codex|\.gemini|\.continue|\.factory|\.hermes|\.kiro|\.mastracode|\.opencode|\.codebuddy|\.pi)(\\|/)'

function Get-FrontmatterField {
    param([string]$Content, [string]$Field)
    if ($Content -match "(?ms)^---\s*\r?\n(.*?)\r?\n---") {
        $yaml = $Matches[1]
        if ($yaml -match "(?m)^${Field}:\s*(.+)$") {
            return $Matches[1].Trim().Trim('"').Trim("'")
        }
    }
    return $null
}

$entries = @()
if (Test-Path $skillsRoot) {
    Get-ChildItem -Path $skillsRoot -Filter 'SKILL.md' -Recurse -File -ErrorAction SilentlyContinue |
        Where-Object { $_.FullName -notmatch $excludePathPattern } |
        ForEach-Object {
            $relative = $_.FullName.Substring($projectRoot.Length).TrimStart('\', '/').Replace('\', '/')
            $content = Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8
            $name = Get-FrontmatterField -Content $content -Field 'name'
            $description = Get-FrontmatterField -Content $content -Field 'description'
            if (-not $name) {
                $name = Split-Path (Split-Path $relative -Parent) -Leaf
            }
            if (-not $description) {
                $description = '(no description in frontmatter)'
            }
            [pscustomobject]@{
                Name        = $name
                Description = $description
                Path        = $relative
            }
        }
}

$deduped = $entries | Sort-Object Path -Unique | Sort-Object Name

$lines = @(
    '# Project Skills Index',
    '',
    '> Auto-generated by `.cursor/hooks/scan-project-skills.ps1`. Do not edit by hand.',
    "> Last updated: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')",
    '',
    '| name | description | path |',
    '| --- | --- | --- |'
)
foreach ($item in $deduped) {
    $desc = $item.Description -replace '\|', '\|' -replace "`r?`n", ' '
    $lines += "| $($item.Name) | $desc | $($item.Path) |"
}

$indexDir = Split-Path $indexPath -Parent
if (-not (Test-Path $indexDir)) {
    New-Item -ItemType Directory -Path $indexDir -Force | Out-Null
}
Set-Content -LiteralPath $indexPath -Value ($lines -join "`n") -Encoding UTF8

$summaryLines = @(
    '## Project skills catalog (auto-injected)',
    "Total: $($deduped.Count) skills under skills/.",
    'Before each task: read .cursor/skills-index.md, match descriptions to the user request, then Read and follow applicable SKILL.md files.',
    ''
)
foreach ($item in $deduped) {
    $summaryLines += "- **$($item.Name)**: $($item.Description) → ``$($item.Path)``"
}

$additionalContext = $summaryLines -join "`n"
$payload = @{
    additional_context = $additionalContext
} | ConvertTo-Json -Compress

[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Write-Output $payload
exit 0

